join public.controls c on c.code = r.code
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000017')
join public.evidence_items ei on ei.name = r.name and ei.framework_id = '00000000-0000-0000-0000-000000000017'
where not exists (
  select 1 from public.evidence_catalog ec
  where ec.control_id = c.id and ec.evidence_item_id = ei.id
);
